#include <stdio.h>
#include <string.h>
#include <ctype.h>

/* Return the Soundex digit for an upper‑case letter.
   0 is returned for letters that are ignored (AEIOUHWY) and for any
   non‑alphabetic character. */
static int soundex_digit(char ch)
{
    switch (ch) {
        case 'B': case 'F': case 'P': case 'V': return 1;
        case 'C': case 'G': case 'J': case 'K':
        case 'Q': case 'S': case 'X': case 'Z': return 2;
        case 'D': case 'T':                     return 3;
        case 'L':                               return 4;
        case 'M': case 'N':                     return 5;
        case 'R':                               return 6;
        default:                                 return 0;   /* A,E,I,O,U,H,W,Y or others */
    }
}

/* Compute the Soundex code of a word.
   The result buffer must have room for at least 5 characters
   (4 characters + terminating NUL). */
static void soundex(const char *word, char out[5])
{
    /* first letter (upper‑cased) */
    out[0] = toupper((unsigned char)word[0]);

    int prev_digit = soundex_digit(out[0]);   /* digit of the first letter – used for duplicate suppression */
    int pos = 1;                              /* next position in out (digits) */

    for (size_t i = 1; word[i] != '\0' && pos < 4; ++i) {
        char ch = toupper((unsigned char)word[i]);
        int d = soundex_digit(ch);
        if (d == 0)               /* ignored letters */
            continue;
        if (d == prev_digit)      /* suppress consecutive duplicates */
            continue;
        out[pos++] = (char)('0' + d);
        prev_digit = d;
    }

    /* pad with zeros if we have fewer than three digits */
    while (pos < 4)
        out[pos++] = '0';

    out[4] = '\0';
}

int main(int argc, char *argv[])
{
    if (argc < 2 || argv[1][0] == '\0') {
        puts("EMPTY");
        return 0;
    }

    char result[5];
    soundex(argv[1], result);
    puts(result);
    return 0;
}
